// documentation for more info.
func (u *DedupSampleUpsertBulk) Update(set func(*DedupSampleUpsert)) *DedupSampleUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&DedupSampleUpsert{UpdateSet: update})
	}))
	return u
}

